(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["zh"] = {"ui":{"skip":"跳到正文","back":"← 返回 AI-gile","lang.button":"语言：{name}","lang.dialog":"选择语言","lang.search":"搜索语言","lang.none":"没有匹配的语言","lang.notYet":"{name} 还没有翻译","theme.aria":"切换主题：浅色、深色或纯黑","theme.toLight":"切换到浅色主题","theme.toDark":"切换到深色主题","theme.toBlack":"切换到纯黑主题（真正的黑色，对 OLED 屏幕友好）","words.underline":"在页面上给这些词加下划线","words.underlineHelp":"把鼠标移到虚线标出的词上或点一下，就能看到它的意思。","words.col.todo":"暂时选定的卡片：团队接下来会从这些开始。","words.col.doing":"有一个 AI 正在处理这张卡片。","words.col.review":"一个 AI 已完成工作，另一个 AI 检查通过后才会交到你手上。","words.col.verify":"等你来：试一试，告诉我们好不好用。","words.col.team":"你的笔记或回答，等团队来接手。","words.col.done":"已完成并通过验收。","index.title":"AI-gile：你的 AI 开发团队，都在一块看板上","index.description":"AI-gile 是给 AI 编程团队用的看板。你睡觉时他们在干活；你只会收到一小堆需要决定、测试和验收的事。","hero.logoAlt":"AI-gile 看板图标","hero.h1.html":"你的 AI 开发团队，都在一块&nbsp;看板上。","hero.alpha":"🐣 封闭预 Alpha","hero.alphaTitle":"还早，也没做完：感谢你来试用！","hero.lede":"你睡觉时他们在开发。醒来只有一小堆事：几个问题，几样要测试的东西，一两颗紫色钻石。点一点，验收，接着去喝你的咖啡。","dl.windows":"Windows 应用","dl.browser":"在浏览器中运行","dl.messenger":"📱 手机版 Messenger","dl.soon":"即将推出","dl.notify":"🔔 开放时通知我","dl.notifySmall":"Alpha 或 Beta","hero.secondary":"敏捷开发，但团队从不需要站会咖啡。（不过他们还是照开站会。）","pitch.h2":"想用几个字介绍 AI-gile，都行","pitch.lede":"选一个长度，从一个字到 144 个字。每个长度都是专门为这个篇幅写的一段介绍。拖动滑块，或用方向键。","pitch.rangeLabel":"字数","pitch.dice":"🎲 换一个版本","pitch.words.one":"{n} 个词","pitch.words.other":"{n} 个词","pitch.letters.one":"{n} 个字母","pitch.letters.other":"{n} 个字母","pitch.chars.one":"{n} 个字","pitch.chars.other":"{n} 个字","count.line.html.one":"看板上现在有 {n} 张卡片","count.line.html.other":"看板上现在有 {n} 张卡片","people.humans.html.one":"👥 {n} 位人类","people.humans.html.other":"👥 {n} 位人类","people.agents.html.one":"🤖 {n} 个智能体","people.agents.html.other":"🤖 {n} 个智能体","people.working.html.one":"⚡ 此刻 {n} 个正在工作","people.working.html.other":"⚡ 此刻 {n} 个正在工作","pre.title":"AI-gile：有东西正在建造","pre.description":"这里正在悄悄建造一些东西：一块让 AI 团队按你的要求来做、还边做边教你的看板。目前是和朋友们一起的封闭预 Alpha。","pre.h1":"这里正在悄悄建造一些东西。 🤫","pre.line":"一块让 AI 团队按你的要求来做、还边做边教你的看板。目前是和朋友们一起的封闭预 Alpha。","pre.btn":"🔔 开放时通知我","pre.peek":"玻璃后面：真实的看板，实时。每张卡片都是一条彩色横条。","pre.peekFake":"玻璃后面：一块正在运转的看板就是这个样子。","pre.night":"🌙 夜间守夜人在掌管一切 · 😴 人类正在休息","features.aria":"它能做什么","f.pile.h":"给你的一小堆","f.pile.html":"<b>待你处理</b>汇集了所有项目里等你的事：问题、要测试的东西、只有人能做的任务。你的队列会告诉你下一件是什么、要花多久。","f.sleep.h":"你睡觉时也在干活的团队","f.sleep.p":"每个项目都有一位负责人和一队 AI 智能体。在卡片上留言，团队就会醒来干活，再带着疲惫的人也能照着做的步骤交还给你。","f.tester.h":"先由 AI 测试员检查","f.tester.p":"东西送到你面前之前，测试员会在应用的副本里照着步骤操作，并附上截图说明看到了什么。通过的快速翻一翻，一键验收。","f.proof.h":"有证据，不画饼","f.proof.p":"每次交付都会列出改了什么：文件、差异、截图。不用逐个打开应用去确认做完没有。","f.chat.h":"和你的负责人聊天","f.chat.p":"类似 Discord 的侧栏：每个项目一个图标，需要你的事用紫色钻石标出。把想法发给负责人，他们会整理成卡片和计划，并附上“✅ 开始”按钮。","f.tidy.h":"自己保持整洁","f.tidy.p":"相关卡片合并成一张，含糊的标题会被改清楚，用量检查让代码保持精简。要切换的东西更少，要操心的也更少。","f.private.h":"归你所有，就在你的电脑上","f.private.li1":"看板运行在你自己的电脑上，只听你的。","f.private.li2":"人与人之间的私信采用端到端加密。","f.private.li3":"没有账号，没有跟踪器，没有 Cookie。","f.lang.h":"说你的语言","f.lang.p":"支持 120 多种语言，从荷兰语、威尔士语、日语，到海盗腔、尤达腔和克林贡语，专业术语还能一键切回英文。","f.service.h":"从一个想法到一项真正的服务","f.service.p":"用 AI 做出了已经有人在用的东西？把它标记为服务，看板就会帮你把它运行好：可用性检查、公开的状态页、附带复盘的事故、需要 Go 才能上线的变更、每天检查的备份。帮助会在你操作时一步步教你。","msgr.h2":"AI-gile Messenger：把团队装进口袋","msgr.p1":"不用打开看板，也能和你的 AI 团队聊天。跟项目负责人和朋友们聊聊，查看卡片的测试步骤并直接回复，全在手机上搞定。","msgr.p2":"扫描看板上的二维码即可配对。第一次用？亲切的演示聊天会带你四处看看。","msgr.when":"先推出 Android 版，接着是适用手机和 iPhone 的网页版。","msgr.who":"你的项目负责人","msgr.b1":"深色模式修好了。要看测试步骤吗？","msgr.b2":"好呀，麻烦了！","msgr.b3":"1. 打开设置。2. 选择深色。看起来对吗？","tl.aria":"从第一次对话到路线图的时间线","tl.h2":"从第一次聊天到接下来的计划","tl.lede":"真实的日期和时间，按你自己的时区显示。今天之后就是计划，不承诺具体日期。","tl.today":"今天","tl.planned":"计划中","tl.doing":"进行中","tl.cards.one":"{n} 张卡片","tl.cards.other":"{n} 张卡片","join.h2":"一起来玩","join.lede":"AI-gile 由一个大胡子怪人（有 AuDHD，跟心理健康打过几场仗）和一大群耐心的智能体打造。目前不公开，只在朋友间封闭内测。开放时想试试吗？","join.btn":"登记兴趣","join.small":"只会给你发邮件，别无其他","footer.tag":"AI-gile。没有跟踪器，没有 Cookie，没有站会咖啡。","footer.licence":"商用许可","footer.status":"状态","footer.privacy":"我们保存什么","footer.thanks":"通话感谢 ChilledChat","form.sending":"发送中…","form.failed":"没成功：请稍后再试。","form.offline":"连不上 AI-gile：请稍后再试。","form.keep":"我们只用它来回复你，之后就会删除。没有跟踪器，没有 Cookie。","form.keepLink":"我们保存什么","interest.title":"AI-gile：Alpha 开放时通知我","interest.description":"留下邮箱，AI-gile 的封闭 Alpha 或 Beta 开放时我们会告诉你。","interest.h1":"🔔 开放时通知我","interest.lede":"AI-gile 正处于封闭预 Alpha 阶段。留下邮箱，等有你的位置时，我们只写一封信。","interest.email":"你的邮箱","interest.which":"哪种测试？","interest.alpha":"封闭 Alpha：早期、粗糙、变化多","interest.beta":"Beta：更稳定，更晚","interest.both":"都行，哪个先开就哪个","interest.submit":"把我加入名单","interest.thanks":"谢谢！你已在名单上。","licence.title":"AI-gile：商用许可","licence.description":"要在公司里使用 AI-gile？可以免费申请商用许可。","licence.h1":"📜 商用许可","licence.lede":"想在工作中使用 AI-gile？告诉我们你是谁、做什么。只要做的事有益处，许可就是免费的。","licence.company":"公司","licence.website":"网站","licence.what":"你做什么","licence.how":"它如何帮助世界","licence.email":"邮箱","licence.submit":"申请","licence.thanks":"谢谢！我们会通过邮件回复。","status.title":"AI-gile 状态","status.h1":"AI-gile 状态","status.quiet":"一切平静","status.intro":"AI-gile 现在正常吗？这个页面每 5 分钟检查一次网站、看板分享、通话和下载。","status.up":"正常运行（{ms} ms 内响应）","status.slow":"上次检查没有响应，正在重试","status.down":"停止运行：最近两次检查都没有响应","status.svc.web":"网站","status.svc.web.offers":"本网站：介绍 AI-gile，以及“开放时通知我”表单","status.svc.boards":"看板分享","status.svc.boards.offers":"公开看板、朋友之间的消息和邀请","status.svc.calls":"通话","status.svc.calls.offers":"AI-gile 里的语音、视频和屏幕共享","status.svc.download":"下载","status.svc.download.offers":"Windows 安装程序和邀请链接","status.checking":"检查中…","status.offline":"暂时连不上状态服务（正在重试）","status.updated":"更新于{ago}","status.justNow":"刚刚","status.min":"{n} 分钟前","status.hours":"{n} 小时前","status.days":"{n} 天前","privacy.title":"AI-gile：我们保存什么","privacy.h1":"我们保存什么","privacy.lede":"简单说：只保存你发给我们的内容，而且不会太久。","privacy.only":"只有你发给我们的内容：你在表单里输入的东西，比如你的邮箱。除此之外，没有任何关于你的信息。","privacy.sealed":"内容会先密封，我们的服务器无法读取：在离开你的浏览器之前就已密封（如果是较旧的浏览器，则在送达的那一刻密封）。只有我们自己的看板能打开它。","privacy.server":"一送达我们的看板，就会从服务器上删除。30 天后仍留在那里的任何内容，也一律删除。","privacy.board":"我们只在回复你之前把它留在看板上，回复后也会从那里删除。","privacy.none":"没有跟踪器，没有 Cookie，没有分析工具。","privacy.local":"你的语言以及浅色或深色的选择只会留在你自己的浏览器里，绝不会发给我们。","privacy.ask":"想早点删除？回复我们的邮件告诉我们就行。","live.h2":"实时看它是怎么建起来的","live.caption":"每张卡片都是隐藏的：你看到的是工作的样子，而不是文字。","live.watching.one":"实时：{n} 人正在看","live.watching.other":"实时：{n} 人正在看","live.last.now":"最近一张卡片刚刚移动","live.last.min.one":"最近一张卡片在 {n} 分钟前移动","live.last.min.other":"最近一张卡片在 {n} 分钟前移动","live.last.hour.one":"最近一张卡片在 {n} 小时前移动","live.last.hour.other":"最近一张卡片在 {n} 小时前移动","live.last.day.one":"最近一张卡片在 {n} 天前移动","live.last.day.other":"最近一张卡片在 {n} 天前移动","live.offline":"实时看板正在稍作休息，请稍后再来看看。","live.cols":"Backlog|待办|进行中|团队检查中|待你测试|交给团队|已完成","footer.models":"AI-gile 会替你调用 AI 模型干活。它们说的话、做的事由它们自己负责，所以在相信之前请先核实。","privacy.ai.h":"AI 部分","privacy.ai.models":"AI-gile 是看板。真正干活的是其他公司的 AI 模型，比如 Claude、Codex 和 Gemini，用的是你自己的账号。","privacy.ai.check":"它们写的内容和做的事都出自它们，可能是错的。在依赖或发布之前，请先检查。","privacy.ai.files":"它们会修改你所连接文件夹里的文件，并运行命令。请做好备份。","privacy.ai.send":"你交给模型的内容会发送给运营它的公司，并适用对方的条款。每家公司各自的条款和费用都会生效。","privacy.ai.asis":"AI-gile 是早期测试版，按现状提供。"},"lines":{"unit":"chars","sizes":[{"n":1,"texts":["看板。","机器人。","放手。"]},{"n":2,"texts":["机器人看板。","智能体，有序。","想法，成真。"]},{"n":3,"texts":["给机器人的看板。","想法变成功能。","免费智能体看板。"]},{"n":5,"texts":["由智能体运转的看板。","你写卡片，智能体来做。","免费、本地、有测试，还有点傻气。"]},{"n":8,"texts":["一块免费的看板，AI 智能体在上面干活。","写下想法，智能体去做，最后由你验收。","给一个人类和一群耐心机器人用的敏捷。"]},{"n":13,"texts":["一块在你电脑上的看板，AI 智能体会自己来领卡片干活。","写下一个想法，一队智能体动手做，再由测试员检查一遍。","免费，没有账号，没有跟踪器：一块看板，几个机器人，你说了算。"]},{"n":21,"texts":["AI-gile 是一块用来和 AI 编程智能体合作的看板。卡片由它们去领，测试和验收则交给你来做。","每个项目都有一位负责人和一队 AI 智能体。你在任意一张卡片上留言，团队就会开始动手干活。","这是一块免费的个人待办看板，就运行在你自己的电脑上。干活的是机器人，点头说好的人是你。"]},{"n":34,"texts":["你把想法放到看板上，一队 AI 智能体把它们做成能用的功能，自己测试一遍，再附上试用步骤交还给你。你没点头之前，没有任何东西算完成。","AI-gile 是一块自制的看板，Rich 在如今被它管理的智能体们的大力帮助下造出了它。它免费，运行在你的电脑上，只分享给朋友，从不出售。","想象一块普通的看板，列从待办排到已完成，只不过卡片是由 AI 智能体来领的。它们会汇报进度，卡住时会提问，而且永远等着你点头同意。"]},{"n":55,"texts":["AI-gile 是一块团队由 AI 智能体组成的看板。每个项目都有一位负责规划的负责人，和几位动手开发的助手。功能做好后，AI 测试员会先试用并截图，然后才放进你的那一小堆。你可以验收，也可以留言，他们就会返工重做。","它起初只是一个人用来同时盯着许多 AI 编程会话的办法，后来慢慢长成了一块像样的看板。它运行在你的电脑上，不需要账号，也没有跟踪器。朋友和好奇的人都可以免费用。它还没做完，所以难免有些毛糙，偶尔也会有小意外。","说句实话：想法还得你来想，结果还得你来看。AI-gile 管的是中间所有的事：让卡片井然有序，你一留言就叫醒该醒的智能体，清楚展示究竟改了什么，再把这一切收进给你的一小堆里。另外它在你的电脑上运行，不要账号，也没有任何跟踪器，完全免费，你想怎么用都行，随时可以停。"]},{"n":89,"texts":["AI-gile 是一块免费的看板，运行在你自己的电脑上。每个项目里干活的不是人，而是一队 AI 智能体：负责人把你的想法整理成卡片和计划，助手则按优先级领取卡片。做好之后，AI 测试员会照着测试步骤操作，并给你看它看到了什么。接着它会放进标着待你处理的那一小堆里等你。你可以验收，也可以留言让团队再来一轮。没有你点头，任何东西都到不了已完成。","有几个你也许想不到的功能。夜班守望会在你睡觉时给待办列补货，专挑不需要你回答的卡片。用量计数器会显示智能体今天和本周用了多少，省用模式则让它们停止消耗。你可以给朋友发消息，私信采用端到端加密。看板支持大约 120 种语言，包括荷兰语、弗拉芒语、海盗腔和克林贡语。这一切一分钱都不收，也没有人想把它卖给你。它运行在你自己的电脑上，不需要账号，也没有跟踪器和 Cookie，数据始终留在你手里。","AI-gile 是一个小小的个人项目，不是公司。Rich 想同时照看好几个 AI 编程项目，又不想挨个打开应用去查看，于是他和智能体们一起造了这块看板，又用这块看板造出了它自己的其余部分。它处于封闭预 Alpha 阶段，意思是对少数几位朋友来说，大体上能用。这里没有价格页，没有新闻邮件，也没有增长计划。如果你觉得有用，等它再开放一些，可以申请试用。"]},{"n":144,"texts":["AI-gile 是给一个人类和许多 AI 智能体用的看板。它运行在你自己的电脑上，完全免费。你添加项目，每个项目都会有一位负责人和一支小团队。你可以和负责人聊天，有点像 Discord，把想法讲给他听；他会把想法整理成卡片和计划，然后等你点下开始。团队按优先级逐张处理卡片，用的是一套专门为语言模型设计的简单命令行。任何东西回到你手里之前，AI 测试员都会在应用的副本里照着步骤操作，并附上截图。做完的工作连同改动的文件和差异，一起落进你的那一小堆。你可以验收，也可以留下一条评论，团队就会醒来再试一次。只有你能把卡片挪到已完成。","大致说说和 AI-gile 度过的一天。傍晚你留下几条评论：这个按钮位置不对，那个列表该排个序，能不能加个深色模式。然后你去睡觉。智能体们读完评论，动手修改，测试，再交还给你。如果待办列空了，夜班守望就从积压清单里补货，挑那些不需要你回答的卡片。早上你面前只有一小堆：几个问题，几样要试的东西，每样都有睡眼惺忪的人也能照做的步骤，还有一张证明它能用的截图。你一路点过去，好的验收，其余的退回，写一句话告诉它们哪里不对就行。用量计数器会告诉你这一切花了多少，节俭的几周还有省用模式可以开。每个项目各有各的负责人，各有各的团队，互不打扰。然后你去吃早餐，这一步智能体暂时还帮不上忙。","先说说 AI-gile 不是什么。它不是创业公司，不对外出售，也没有人在收集你的数据。它是一块免费的看板，运行在你的电脑上，没有账号，没有跟踪器，也没有 Cookie。它是什么呢：一个整洁的地方，能一眼看到所有 AI 编程项目，一队智能体负责做卡片，决定则由你来下。它会把相关的卡片合并，把含糊的标题改清楚，还留意代码是不是保持精简。它支持大约 120 种语言，从荷兰语、弗拉芒语到海盗腔和克林贡语。朋友之间可以私下发消息，而且是加密的。它由 Rich 和一大群耐心的智能体打造，多半是靠它自己来完成的。它仍处于封闭预 Alpha 阶段，有些地方还很粗糙。如果听起来有趣，客气地问一问，也许你能提前进来。"]}],"quips":{"1":"就一个词。够大胆。也许太大胆了。","3":"三个词。已经比大多数产品页更诚实了。","8":"八个词。还是比一次站会短。","21":"顺便说一句，这些长度是故事点数。那当然。","55":"五十五个词。你读这段的工夫，有两张卡片做完了。","144":"这是最长的一版。没有 233 了。智能体已经去睡了。"}},"timeline":{"first-idea.name":"最初的想法","first-idea.line":"第一次对话，那时还没有任何代码。","first-board.name":"第一块看板","first-board.line":"一块记录自己如何被造出来的看板：卡片、列、拖放、项目。","team-roles.name":"团队与角色","team-roles.line":"智能体档案、团队模板、空间，以及谁负责什么。","install.name":"安装与发布","install.line":"朋友也能安装的压缩包、自动更新、渠道和回滚。","usage-saver.name":"用量节省","usage-saver.line":"衡量每次运行的花费，保持代码精简，省下你的额度。","friends.name":"好友与分享","friends.line":"私信、加扰中继、邀请、角色和共享项目。","languages.name":"语言","languages.line":"所有界面文字都放进语言文件，先有荷兰语和弗拉芒语。","ai-tester.name":"AI 测试员","ai-tester.line":"每次交付先由测试员检查，并展示它看到的内容。","website.name":"网站","website.line":"aigile.lol、预告页和这条时间线。","streaming.name":"聊天与直播","streaming.line":"Discord、Twitch、OBS、主播模式、GIF 和表情。","no-ai.name":"无 AI 版","no-ai.line":"给不用 AI 写代码的人用的看板，以及公开看板。","night-watch.name":"夜班守望","night-watch.line":"守夜人和 Scrum Master 在你睡觉时盯着团队干活。","p-more.name":"其他一切","p-more.line":"还在排队等轮到的小想法。","p-android.name":"手机与安卓","p-android.line":"先用手机访问你的看板，再做原生安卓应用。","p-release.name":"Alpha 及以后","p-release.line":"封闭 Alpha、正式上线的网站，然后是 Beta。","p-languages.name":"更多语言","p-languages.line":"130 种语言，还有面向学习者的语言沉浸模式。","p-engines.name":"更多 AI 引擎","p-engines.line":"每个智能体都可以选用 Claude、Codex、Gemini、Copilot 或 Cursor。","p-pro.name":"专业实践","p-pro.line":"风险标签、合并关卡、事故卡片和护栏。","p-self.name":"照顾你自己","p-self.line":"疲惫模式、自我关怀提醒和 4:20。","p-servers.name":"服务器与规模","p-servers.line":"全局服务器设置、角色，以及为增长做的规划。","p-livestream.name":"直播附加功能","p-livestream.line":"Twitch 聊天、自定义表情和公开的直播视图。"},"words":{"button":"📖 专业术语","h":"📖 词语解释","intro":"通俗易懂的免费培训：从最初的想法到人们依赖的服务，你会遇到的每个词都在这里，沿途还涵盖敏捷、开发、保障安全，以及与 AI 合作。","search":"搜索词语…","none":"没有匹配的词。","close":"关闭","count":{"one":"{count} 个词","other":"{count} 个词"},"groups":[{"id":"idea","name":"💡 想法与探索"},{"id":"plan","name":"🗺️ 规划工作"},{"id":"agile","name":"🔁 敏捷工作方式"},{"id":"build","name":"🛠️ 做出来"},{"id":"test","name":"🧪 测试与质量"},{"id":"change","name":"🔀 安全地改动"},{"id":"run","name":"🛎️ 运行一项服务"},{"id":"sec","name":"🔒 安全与隐私"},{"id":"ai","name":"🤖 与 AI 合作"},{"id":"money","name":"💰 费用与许可"}],"list":[{"id":"discovery","g":"idea","word":"探索期（Discovery）","text":"最早的阶段：在动手做任何东西之前，先弄清楚哪个问题值得解决、是为谁解决。","also":["探索阶段","发现阶段","discovery phase"]},{"id":"problemstmt","g":"idea","word":"问题陈述","text":"用一两句话说清楚谁有什么问题、为什么重要，让大家朝着同一个目标努力。","also":["问题陈述","problem statements"]},{"id":"user","g":"idea","word":"用户","text":"使用你所做东西的人。做这些工作，就是为了满足他们的需要。","also":["用户","使用者","users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"利益相关方","text":"关心工作结果、或会受其影响的人，比如出钱的人、使用的人和提供支持的人。","also":["利益相关者","干系人","stakeholders"]},{"id":"persona","g":"idea","word":"用户画像（Persona）","text":"一个虚构但真实可信的人物，代表某一类用户，让团队可以问：“小山会觉得这个好用吗？”","also":["用户画像","人物角色","personas"]},{"id":"userresearch","g":"idea","word":"用户研究","text":"和真实的人交谈、观察他们，了解他们的需要，而不是靠猜。","also":["用户研究","用户访谈","user interviews"]},{"id":"journey","g":"idea","word":"用户旅程","text":"一个人完成某件事所经历的步骤，从第一次听说到最后做完，也包括在你的产品之外的部分。把它画出来，就能看出他们在哪里卡住。","also":["用户旅程","客户旅程","user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"痛点","text":"现在让人烦恼或拖慢人的事情。好的产品会把痛点消除。","also":["痛点","pain points"]},{"id":"assumption","g":"idea","word":"假设","text":"你相信、但还没有验证过的事。把假设写下来，就知道该先测试什么。","also":["假设","assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"假说","text":"你打算去验证的最佳猜测，并写明你预期会发生什么，比如“第一个月免费的话，大家就会注册”。","also":["假说","hypotheses"]},{"id":"experiment","g":"idea","word":"实验","text":"一次有计划的小测试，在下大赌注之前先弄清楚一个想法行不行得通。","also":["实验","experiments"],"noTip":1},{"id":"poc","g":"idea","word":"概念验证（PoC）","text":"快速做个粗糙的尝试，看看一个想法到底行不行。有了答案之后，通常就扔掉。","also":["PoC","概念验证","proof of concept"]},{"id":"prototype","g":"idea","word":"原型","text":"产品的早期模型，常常是可以点击的图片，在正式制作之前先让人试用这个想法。","also":["原型","prototypes"]},{"id":"wireframe","g":"idea","word":"线框图","text":"一张简单的界面草图，只标出各样东西放在哪里，没有颜色，也没有真实内容。","also":["线框图","wireframes"]},{"id":"mockup","g":"idea","word":"效果图（Mockup）","text":"一张详细的图，展示界面最终的样子，有真实的颜色和文字，但还什么都点不动。","also":["效果图","视觉稿","mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"商业论证","text":"做一个项目的理由：要花多少钱、能带来或省下多少、有哪些风险。","also":["商业论证","商业案例","business cases"]},{"id":"feasibility","g":"idea","word":"可行性","text":"以你现有的时间、资金和技能，这件事是否真的能做出来并维护下去。","also":["可行"]},{"id":"outcome","g":"idea","word":"成果（Outcome）","text":"你希望为人们带来的改变，比如少一些错过的预约。它比做了多少东西更重要。","also":["成果","效果","outcomes"],"noTip":1},{"id":"output","g":"idea","word":"产出（Output）","text":"团队做出来的东西，比如一个新界面或一份报告。做出来并不等于对谁有帮助。","also":["产出","交付物","outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"成功指标","text":"一个数字，告诉你这项工作有没有达到目的，比如有更多人完成了下单。","also":["成功指标","success metrics"]},{"id":"kpi","g":"idea","word":"关键绩效指标（KPI）","text":"用来看事情进展顺不顺利的重要数字，比如每周注册人数。","also":["KPI","KPIs","关键绩效指标","key performance indicator"]},{"id":"okr","g":"idea","word":"目标与关键成果（OKR）","text":"一种设定目标的方法：目标说明你想要什么，几个关键成果则是证明你做到了的数字。","also":["OKR","OKRs","目标与关键成果"]},{"id":"product","g":"plan","word":"产品","text":"为用户而开发和维护的东西，比如应用、网站或工具。","also":["产品","products"],"noTip":1},{"id":"vision","g":"plan","word":"产品愿景","text":"一段简短的话，说明产品帮助谁，以及长远来看要走向哪里。","also":["愿景","愿景宣言","vision statement"]},{"id":"po","g":"plan","word":"产品负责人（PO）","text":"决定做什么、按什么顺序做的人，让团队始终做最重要的事。在 AI-gile 里，这个人就是你。","also":["PO","产品负责人","product owners"]},{"id":"pm","g":"plan","word":"产品经理（PM）","text":"负责产品方向的人：它解决哪些问题、为谁解决、为什么。PM 也可能指项目经理，所以要看清是哪一种。","also":["产品经理","product managers"]},{"id":"projmgr","g":"plan","word":"项目经理","text":"让项目按时、不超预算的人，负责跟进谁在什么时候做什么。","also":["项目经理","project managers"]},{"id":"roadmap","g":"plan","word":"路线图","text":"对未来几个月要做什么的大致计划，按先后排列。它显示方向而不是确切日期，会随着你的了解而调整。","also":["路线图","roadmaps"]},{"id":"milestone","g":"plan","word":"里程碑","text":"项目中值得标记的一个节点，比如“第一版上线”或“达到 100 位用户”。","also":["里程碑","milestones"]},{"id":"mvp","g":"plan","word":"最小可行产品（MVP）","text":"仍然对真实用户有用的最小版本，这样你能尽早向他们学习。","also":["MVP","MVPs","最小可行产品","minimum viable product"]},{"id":"requirement","g":"plan","word":"需求","text":"做好的产品必须能做到或必须具备的东西。","also":["需求","requirements"],"noTip":1},{"id":"scope","g":"plan","word":"范围","text":"工作包含什么，以及同样重要的：不包含什么。","also":["范围内","范围外","in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"范围蔓延","text":"工作内容一点一点越加越多，却没人同意多花时间或费用，结果永远做不完。","also":["需求蔓延","功能蔓延","feature creep"]},{"id":"feature","g":"plan","word":"功能","text":"产品能为人做的一件事，比如“重设密码”。","also":["功能","features"],"noTip":1},{"id":"epic","g":"plan","word":"史诗（Epic）","text":"一大块工作，一次做不完，所以要拆成较小的卡片。","also":["史诗","epics"]},{"id":"story","g":"plan","word":"用户故事","text":"从用户角度写的一小块工作：“作为购物者，我想保存购物篮，以便稍后再结账。”它是讨论该做什么的起点。","also":["用户故事","user stories"]},{"id":"ac","g":"plan","word":"验收标准（AC）","text":"一张卡片要算完成所必须通过的检查，在开工前就谈好，比如“退出再登录后，购物篮里的东西还在”。","also":["验收标准","acceptance criteria"]},{"id":"task","g":"plan","word":"任务","text":"一件要做的具体事情，通常是一个较大故事中的一小步。","also":["任务","tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"工单","text":"卡片的另一种叫法：一项工作或一个请求，从开始到结束全程跟踪。","also":["工单","tickets"]},{"id":"priority","g":"plan","word":"优先级","text":"相比其他事情，某件事有多重要或多紧急，让最重要的工作先做。","also":["优先级","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"排优先级","text":"按重要程度给工作排序。常见的方法是 MoSCoW：必须有、应该有、可以有、这次不做。","also":["排优先级","优先排序","MoSCoW"]},{"id":"estimate","g":"plan","word":"估算","text":"对一项工作有多大、要多久的最佳猜测。它只是猜测，不是承诺。","also":["估算","估计","estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"故事点","text":"通过卡片之间互相比较（“大约是那张的两倍”）而不是用小时来估计工作量的方法。故事点不是用来比较不同团队的。","also":["故事点","story point"]},{"id":"tshirt","g":"plan","word":"T 恤尺码估算","text":"把工作量估成 S、M、L 或 XL。又快又够用，适合早期规划。","also":["T恤尺码","t-shirt sizes"]},{"id":"poker","g":"plan","word":"规划扑克","text":"一种估算游戏：大家同时亮出代表大小的牌，然后出最高和最低的人说明理由。","also":["估算扑克","Scrum poker"]},{"id":"dependency","g":"plan","word":"依赖关系","text":"一项工作必须等另一项开始或完成，自己才能开始或完成。","also":["依赖","依赖关系","dependencies"]},{"id":"blocker","g":"plan","word":"阻碍","text":"现在让工作无法继续的任何事，比如还没得到答复或工具坏了。","also":["阻碍","卡点","blockers"]},{"id":"deadline","g":"plan","word":"截止日期","text":"某件事必须完成的日期。","also":["截止日期","最后期限","deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"交付物","text":"工作产出并交出去的具体东西，比如一个能用的页面或一份报告。","also":["交付物","可交付成果","deliverables"]},{"id":"forecast","g":"plan","word":"预测","text":"根据目前所知，对可能发生的事（比如工作什么时候完成）做出的预判。","also":["预测","forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"指标","text":"任何你持续测量和追踪的东西，比如页面访问量或修复一个问题要多久。","also":["指标","度量","metrics"]},{"id":"feedback","g":"plan","word":"反馈","text":"别人对你的工作说的话，无论好坏。尽早、经常地得到反馈，是敏捷的核心。","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"尚未排进计划的想法和工作的等候清单，最重要的放在最上面。在移到“待办”之前，那里的东西都不会有人去做。"},{"id":"sprint","g":"agile","word":"迭代","text":"一段短而固定的工作时间（通常一到两周，最长不超过一个月），有一个目标和一组商定要完成的卡片。","also":["Sprint","sprints"]},{"id":"standup","g":"agile","word":"站会","text":"每天一次的快速碰头：每位成员做了什么、接下来做什么、有什么阻碍。在 Scrum 里叫每日 Scrum。","also":["站会","每日站会","standup","stand-ups","daily scrum","daily stand-up"]},{"id":"kanban","g":"agile","word":"看板","text":"一种工作方式：卡片在看板的各列之间移动（比如待办、进行中、已完成），团队限制同时进行的数量，让工作持续流动。"},{"id":"wip","g":"agile","word":"WIP 限制","text":"WIP 是在制品（work in progress）的缩写。WIP 限制是一列最多可以同时放几张卡片，让团队先把事情做完，再开始新的。","also":["WIP"]},{"id":"dod","g":"agile","word":"完成的定义","text":"团队关于“完成”是什么意思的简短清单，比如已测试、已说明，然后才把卡片交给你。它的双胞胎“就绪的定义”，说的是卡片什么时候清楚到可以开工。","also":["就绪的定义","DoD","DoR","Definition of Ready"]},{"id":"retro","g":"agile","word":"回顾会","text":"定期回头看团队是怎么工作的，商定一两件下次能做得更好的事。是 retrospective 的简称。在 AI-gile 里，回顾会会提议改动团队的工作方式，由你回答 Go 或“还不行”。","also":["回顾","retro","retros","retrospective","retrospectives"]},{"id":"swarm","g":"agile","word":"蜂群","text":"全员上阵：许多人放下手头别的工作，一起处理一件紧急的事，直到解决为止。在 AI-gile 里，每个团队都来帮一个项目，其他项目暂时等着。","also":["集中攻关","swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"在 Scrum 里，帮助团队顺利工作的人：清除他们的阻碍、让会议保持在正轨上、指导好习惯，而不是对人发号施令。在 AI-gile 里，首席 Scrum Master 会在所有项目中发现卡住的卡片、提醒各团队，并提醒你有什么在等你。","also":["首席 Scrum Master","Lead Scrum Master"]},{"id":"agile","g":"agile","word":"敏捷（Agile）","text":"一种分小步的工作方式：先做一点，经常展示真实成果，从大家的意见中学习，边做边调整计划，而不是一开始就把一切都规划好。","also":["敏捷","敏捷开发","Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"敏捷宣言","text":"软件开发者在 2001 年写下的一段简短宣言。它把人、能运行的成果、与客户密切合作和应对变化，放在繁重的计划和文书工作之前。","also":["敏捷宣言","敏捷软件开发宣言","Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"瀑布模型","text":"较老的工作方式：先把一切计划好，再全部做出来，然后全部测试，一个阶段接一个阶段。到了后期再改动，既困难又昂贵。","also":["瀑布模型","瀑布式","waterfall model"]},{"id":"iteration","g":"agile","word":"迭代（Iteration）","text":"一轮“做出东西、检查、改进”的过程。敏捷工作就是由一连串迭代组成的，Scrum 里的迭代（Sprint）就是其中一种。","also":["迭代","iterations"]},{"id":"increment","g":"agile","word":"增量","text":"在一个迭代或一轮工作中加到产品里的一块新的、能用的部分，并且能与原有的部分配合起来。","also":["增量","increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"一种流行的敏捷工作方式：一个小团队在一个个短迭代里朝着一个目标努力，有固定的角色和几个定期的会议，用来计划、检查和改进。"},{"id":"scrumteam","g":"agile","word":"Scrum 团队","text":"Scrum 里做事的那个小组：一位产品负责人、一位 Scrum Master 和开发人员。","also":["Scrum 团队","Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Scrum 事件","text":"Scrum 里的定期会议：迭代计划会、每日 Scrum、迭代评审会和回顾会。很多人把它们叫作“仪式”（ceremonies）。","also":["Scrum 事件","Scrum 会议","仪式","ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"迭代计划会","text":"迭代开始时的会议，团队在会上商定这个迭代为什么重要、要接哪些卡片，以及怎么着手。","also":["迭代计划会","冲刺计划会","计划会议","sprint planning","planning meeting"]},{"id":"sprintgoal","g":"agile","word":"迭代目标","text":"用一句话说明这个迭代是为了什么。小任务可以在途中调整，只要目标达成就行。","also":["迭代目标","冲刺目标","sprint goal","sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"迭代 Backlog","text":"为当前迭代挑选出来的卡片，以及团队完成它们的计划。","also":["迭代 Backlog","迭代待办列表","冲刺待办列表","sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"产品 Backlog","text":"为产品可能要做的所有事情排好序的完整清单，最重要的在最上面。它会随着你的了解不断变化。","also":["产品 Backlog","产品待办列表","product backlogs"]},{"id":"productgoal","g":"agile","word":"产品目标","text":"产品努力要达成的更大成果，帮助团队决定下一步做什么。","also":["产品目标","product goals"]},{"id":"refinement","g":"agile","word":"Backlog 梳理","text":"定期过一遍 Backlog，整理、拆分、排序，并给卡片补充细节，让它们随时可以接手。也叫 backlog grooming。","also":["Backlog 梳理","待办列表梳理","需求梳理","backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"迭代评审会","text":"迭代结束时的会议，团队展示完成的东西，听取大家的想法，以决定接下来做什么。","also":["迭代评审会","冲刺评审会","迭代评审","sprint reviews"]},{"id":"demo","g":"agile","word":"演示（Demo）","text":"把完成的工作实时运行起来，展示给提出需求的人看。","also":["演示","demos"],"noTip":1},{"id":"timebox","g":"agile","word":"时间盒","text":"给某件事设定的一段固定时间。时间一到就停下来，即使没有全部做完。","also":["时间盒","限时","timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"速度（Velocity）","text":"团队在一个迭代里通常能完成多少工作，用来计划下次接多少。它不是衡量大家多努力的分数。","also":["速度","团队速度","team velocity"]},{"id":"capacity","g":"agile","word":"产能","text":"扣除假期和其他工作之后，团队在一段时间内能接下多少工作。","noTip":1},{"id":"burndown","g":"agile","word":"燃尽图","text":"显示一个迭代里剩余工作逐日下降的图。如果线一直是平的，就说明有东西卡住了。","also":["燃尽图","burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"燃起图","text":"显示已完成的工作随时间上升的图，旁边是计划的总量，让你看出什么时候能做完。","also":["燃起图","burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"看板","text":"就是这块看板本身：工作的每个阶段一列，卡片在各列之间移动。","also":["看板","Kanban 看板","Kanban boards"]},{"id":"pullsys","g":"agile","word":"拉动式系统","text":"一种工作方式：只有当有人腾出手来时才开始新工作，而不是把活硬塞给已经满负荷的人。","also":["拉动式系统","拉式","pull-based"]},{"id":"flow","g":"agile","word":"流动","text":"工作在看板上移动得有多顺畅。流动良好，就是卡片不断向前，而不是堆积起来。","also":["流动","工作流动","flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"前置时间","text":"从有人提出需求到它完成，一共要多长时间。","also":["前置时间","交付周期","lead times"]},{"id":"cycletime","g":"agile","word":"周期时间","text":"一张卡片从真正开始动工到完成要多长时间。","also":["周期时间","循环时间","cycle times"]},{"id":"throughput","g":"agile","word":"吞吐量","text":"一周内（或任何固定时间内）完成了多少张卡片。","also":["吞吐量","产出率","throughput rate"]},{"id":"bottleneck","g":"agile","word":"瓶颈","text":"工作堆积、拖慢后面一切的那个环节，就像瓶子细细的瓶颈。","also":["瓶颈","bottlenecks"]},{"id":"swimlane","g":"agile","word":"泳道","text":"看板上横贯的一行，把同一类卡片归在一起，比如紧急的工作或某个团队的卡片。","also":["泳道","swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"精益（Lean）","text":"一种工作方式：去掉浪费（任何对客户没有帮助的东西），让工作持续流动。"},{"id":"waste","g":"agile","word":"浪费","text":"在精益里，指任何要花力气、却对客户没有帮助的事，比如等待、返工，或做出没人用的东西。","noTip":1},{"id":"kaizen","g":"agile","word":"持续改进","text":"通过经常做一些小的改动、再检查是否有帮助，让自己一点一点不断变好。回顾会就是其中一种方法。也叫 kaizen（改善）。","also":["持续改进","改善","kaizen"]},{"id":"selforg","g":"agile","word":"自组织团队","text":"自己决定怎么做事的团队，而不是被人一步一步告知该怎么做。","also":["自组织团队","自组织","自我管理团队","self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"跨职能团队","text":"拥有完成工作所需的全部技能的团队，比如设计、开发和测试，自己就能做完。","also":["跨职能团队","跨职能","cross-functional"]},{"id":"spike","g":"agile","word":"探针任务（Spike）","text":"一小段限时的调研，在投入真正的工作之前，先回答一个问题。","also":["探针任务","探究任务","spikes"]},{"id":"rework","g":"agile","word":"返工","text":"因为第一次没做对，所以把工作再做一遍。","also":["返工","重做","reworked"]},{"id":"safe","g":"agile","word":"规模化敏捷（SAFe）","text":"在大型组织里让许多团队一起用敏捷的方法。SAFe（规模化敏捷框架）就是其中一个著名的例子。","also":["规模化敏捷","scaled Agile"]},{"id":"repo","g":"build","word":"仓库","text":"项目的代码文件夹，附带完整的提交历史。它可以放在你的电脑上、GitHub 上，或者两边都有。","also":["repository","Repo","repo"]},{"id":"branch","g":"build","word":"分支","text":"代码中一条独立的工作线，这样就能在不碰主版本的情况下做改动。","also":["branches","Branch"]},{"id":"commit","g":"build","word":"提交","text":"代码的一次已保存快照，附有一句改动说明。你随时可以回到某一个快照。","also":["Commit","commit","commits"]},{"id":"push","g":"build","word":"推送","text":"把你保存好的快照（提交）从这台电脑发送到网上的共享副本（比如 GitHub），这样它们有了备份，别人也能拿到。"},{"id":"merge","g":"build","word":"合并","text":"把一个分支的改动并入另一个分支，通常是并回主版本。"},{"id":"pr","g":"build","word":"拉取请求","text":"请求把一个分支的改动经过检查后合并到主版本。有些网站把它叫作合并请求。","also":["PR","PRs","合并请求","merge request"]},{"id":"refactor","g":"build","word":"重构","text":"在不改变功能的前提下整理代码：文件更小、命名更清晰、重复更少。"},{"id":"bug","g":"build","word":"Bug","text":"某样东西没有按预期正常工作。","also":["bugs","缺陷"]},{"id":"peerreview","g":"build","word":"同行评审","text":"多一双眼睛：由作者以外的人在成果送到你手上之前先检查，这样漏过去的错误更少。在 AI-gile 里，每张卡片由另一个 AI 来检查。","also":["代码评审","peer review","code review"]},{"id":"code","g":"build","word":"代码","text":"告诉电脑要做什么的书面指令。也叫源代码。","also":["代码","源代码","source code"],"noTip":1},{"id":"proglang","g":"build","word":"编程语言","text":"用来写代码的语言，比如 JavaScript、Python 或 Java。不同的语言适合不同的工作。","also":["编程语言","programming languages"]},{"id":"developer","g":"build","word":"开发者（dev）","text":"编写和修改代码的人。也叫程序员或软件工程师。","also":["开发者","开发人员","程序员","软件工程师","developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"软件","text":"在电脑和手机上运行的程序，与机器本身（硬件）相对。","noTip":1},{"id":"app","g":"build","word":"应用（App）","text":"应用程序（application）的简称：人们用来完成某件事的程序，在手机、电脑或网页浏览器里都有。","also":["应用","App","apps","application","applications","应用程序"],"noTip":1},{"id":"webapp","g":"build","word":"网页应用","text":"在网页浏览器里运行的应用，所以不需要安装任何东西。","also":["网页应用","Web 应用","web apps","web application"]},{"id":"frontend","g":"build","word":"前端","text":"应用中你能看到并点击的部分：界面、按钮和文字，通常就在你的浏览器里。","also":["前端","front-end","frontend"]},{"id":"backend","g":"build","word":"后端","text":"应用在幕后的那一部分，保存数据，并在你点击某样东西时干活，比如核对你的密码。","also":["后端","back-end","backend"]},{"id":"fullstack","g":"build","word":"全栈","text":"前端和后端都能做。","also":["全栈","full-stack"]},{"id":"ui","g":"build","word":"用户界面（UI）","text":"一个人在屏幕上看到并使用的东西：布局、按钮、菜单和文字。","also":["UI","用户界面","user interface"]},{"id":"ux","g":"build","word":"用户体验（UX）","text":"使用某样东西的感受：轻松、清楚、愉快，还是混乱又缓慢。","also":["UX","用户体验","user experience"]},{"id":"accessibility","g":"build","word":"无障碍（a11y）","text":"让所有人都能使用，包括视力不好、不能用鼠标或使用读屏软件的人。","also":["无障碍","可访问性","a11y"]},{"id":"responsive","g":"build","word":"响应式设计","text":"让页面在各种尺寸的屏幕上都能正常显示、好用，从手机到大显示器都一样。","also":["响应式设计","自适应设计"]},{"id":"designsys","g":"build","word":"设计系统","text":"一套共用的颜色、字体、按钮和规则，让每个界面看起来和用起来都是一个样。","also":["设计系统","design systems"]},{"id":"architecture","g":"build","word":"架构","text":"一个系统的整体形态：主要有哪些部分，以及它们怎样互相沟通。"},{"id":"database","g":"build","word":"数据库（DB）","text":"有条理地存放信息的地方，就像一张非常强大的电子表格，应用可以读取和修改它。","also":["数据库","database","databases","DB"]},{"id":"schema","g":"build","word":"数据库结构（Schema）","text":"数据库的布局：它有哪些信息表，每张表里放什么。","also":["数据库结构","表结构","schema"]},{"id":"sql","g":"build","word":"SQL","text":"结构化查询语言（structured query language）的缩写：许多数据库都用它来查询信息或修改信息。","also":["结构化查询语言","Structured Query Language"]},{"id":"data","g":"build","word":"数据","text":"电脑保存的信息，比如姓名、订单或设置。","also":["数据","资料","dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"服务器","text":"一直开着、回应其他电脑请求的电脑，比如你访问网页时把网页发给你。","also":["服务器","servers"]},{"id":"client","g":"build","word":"客户端","text":"提出请求的一方，通常是你的浏览器或应用，去和服务器沟通。在商务场合，它也可以就是指客户。","also":["客户端","clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"应用程序接口（application programming interface）的缩写：一份固定的“菜单”，列出一个程序可以向另一个程序提出哪些请求，就像向天气服务询问今天的预报。","also":["APIs","应用程序接口","application programming interface"]},{"id":"endpoint","g":"build","word":"端点","text":"API 菜单上的一项：程序可以调用的一个网址，用来获取或发送某样东西。","also":["端点","接口地址","endpoints"]},{"id":"integration","g":"build","word":"集成","text":"把两个系统连起来让它们一起工作，比如你的网店把订单发送到你的会计软件。","also":["集成","对接","integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"某件事一发生，一个系统就自动发给另一个系统的消息，比如“已收到付款”。","also":["网络钩子","webhooks"]},{"id":"library","g":"build","word":"库（Library）","text":"别人写好的现成代码，你可以直接重复使用，而不用自己写。","also":["库","代码库","libraries"],"noTip":1},{"id":"framework","g":"build","word":"框架","text":"用来开发应用的现成结构，决定了代码大部分的组织方式，就像一座房子的骨架，由你来填充。","also":["框架","frameworks"]},{"id":"sdk","g":"build","word":"软件开发工具包（SDK）","text":"一整套工具、代码和示例，用来为某个平台或服务开发软件。","also":["SDK","SDKs","软件开发工具包"]},{"id":"softdep","g":"build","word":"软件依赖项","text":"你的代码要运行所需要的库或工具。为了安全，保持它们是最新版本很重要。","also":["软件依赖项","软件依赖","software dependencies"]},{"id":"package","g":"build","word":"包","text":"一组打包好的现成代码，你可以安装并用在项目里。","also":["包","软件包","packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"包管理器","text":"帮你获取并更新代码所依赖的包的工具。npm 是常见的一个。","also":["包管理器","package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"最常用的工具，用提交和分支的形式记录代码改动的历史。"},{"id":"github","g":"build","word":"GitHub","text":"一个在线保存 Git 仓库的网站，让团队可以共享代码、审查改动和跟踪工作。"},{"id":"vcs","g":"build","word":"版本控制","text":"保留文件每一次改动的完整历史，让你看到谁改了什么，需要时可以退回去。Git 就是这样做的。","also":["版本控制","源代码管理","source control","version control system"]},{"id":"clone","g":"build","word":"克隆","text":"在你自己的电脑上，做一份包含历史记录的仓库完整副本。","also":["克隆","clone","cloned","cloning"]},{"id":"pull","g":"build","word":"拉取（Pull）","text":"把共享副本（比如 GitHub）上最新的提交取到你的电脑上。与推送（push）相反。","also":["拉取","pull","git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"主分支","text":"大家都以它为基础工作的正式版本代码，通常叫 main 或 master。","also":["主分支","main 分支","master branch"]},{"id":"conflict","g":"build","word":"合并冲突","text":"两处改动以不同的方式改了同样的几行，电脑无法把它们合起来，必须由人来选择。","also":["合并冲突","冲突","merge conflicts"]},{"id":"diff","g":"build","word":"差异（Diff）","text":"一个视图，精确显示两个版本之间改了什么：新增了哪些行，去掉了哪些行。","also":["差异","diff","diffs"]},{"id":"fork","g":"build","word":"复刻（Fork）","text":"别人仓库的一份你自己的副本，你可以随意修改，而不会影响原来的仓库。","also":["复刻","fork","forks","forked"]},{"id":"script","g":"build","word":"脚本","text":"一小段能自己完成一件事的程序，比如整理文件或启动应用。","also":["脚本","scripts"],"noTip":1},{"id":"build","g":"build","word":"构建","text":"把代码变成可以运行的东西，或者指构建出来的这个可运行成品。","also":["构建","builds"],"noTip":1},{"id":"compile","g":"build","word":"编译","text":"把人写的代码翻译成电脑可以直接运行的形式。","also":["编译","编译器","compiler"]},{"id":"cli","g":"build","word":"命令行（CLI）","text":"一个文字窗口，你在里面输入指令让电脑执行，而不是用鼠标点击。也叫终端。","also":["命令行","CLI","终端","command line","command-line","terminal"]},{"id":"config","g":"build","word":"配置（config）","text":"控制软件行为的各项设置，与代码分开存放，方便修改。","also":["配置","设置","config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"环境变量","text":"程序启动时交给它的一项设置，常用来放地址或密码，这样它们就不用写进代码里。","also":["环境变量","environment variables","env var"]},{"id":"debugging","g":"build","word":"调试（Debug）","text":"找出某样东西为什么不能用，并把它修好。","also":["调试","排错","debug","debugged"]},{"id":"pairing","g":"build","word":"结对编程","text":"两个人（或一个人加一个 AI）一起处理同一份代码，一个人打字，另一个人检查。","also":["结对编程","pairing"]},{"id":"docs","g":"build","word":"文档（docs）","text":"书面的说明，讲清楚某样东西是怎么运作的或怎么使用。","also":["文档","说明文档","documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"仓库里最先该读的文件：这个项目是什么，以及怎么让它跑起来。","also":["README","自述文件","READMEs"]},{"id":"legacy","g":"build","word":"遗留系统","text":"仍在使用、却很难修改的老系统，往往因为还懂它的人已经不多。","also":["遗留系统","旧系统","遗留代码","legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"技术债","text":"现在省时间、日后却让修改变慢的捷径，就像会不断累积利息的贷款。重构就是在还债。","also":["技术债","技术债务","tech debt"]},{"id":"test","g":"test","word":"测试","text":"检查某样东西是否按应有的方式运作。有些测试由电脑在代码每次变动时自动运行；有些是你在接受之前亲自试用做好的卡片。","also":["tests","Test"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"质量保证（quality assurance）的缩写：为确保工作在上线前是正确的所做的一切。在 AI-gile 里指的是自动检查：QA 为红色就表示有东西没通过，修好之前不能上线。","also":["质量检查","质量保证","quality assurance","quality checks"]},{"id":"testpile","g":"test","word":"测试队列","text":"等你来试的已完成卡片，一张接一张。接受一张，或者附上说明退回去，下一张就出来了。","also":["test pile","test piles"]},{"id":"autotest","g":"test","word":"自动化测试","text":"每次代码变动时电脑自动执行的检查，用来尽早发现错误。","also":["自动化测试","自动测试","automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"手动测试","text":"由人亲手试用成果，看它的表现是否符合预期。","also":["手动测试","人工测试","manual tests","manual testing"]},{"id":"unittest","g":"test","word":"单元测试","text":"对一小段代码单独做的小型自动检查。","also":["单元测试","unit tests"]},{"id":"integtest","g":"test","word":"集成测试","text":"检查多个部分合在一起是否正常运作，而不是一个一个地检查。","also":["集成测试","integration tests"]},{"id":"endtoend","g":"test","word":"端到端测试（E2E）","text":"像真实用户一样从头到尾走一遍的测试，比如注册、购买、付款。","also":["E2E","端到端","端到端测试","end-to-end tests"]},{"id":"uat","g":"test","word":"用户验收测试（UAT）","text":"由提出需求的人亲自试用，并说明它是否满足他们的需要。AI-gile 的测试队列就是这种做法。","also":["UAT","验收测试","acceptance testing"]},{"id":"regression","g":"test","word":"回归","text":"原本能用、改动之后却坏掉的东西。回归测试就是检查旧功能是否仍然正常。","also":["回归","回归测试","regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"冒烟测试","text":"非常快速的检查，看主要功能到底能不能用，比如刚上线一项改动之后。如果不通过，就先停下来查看。","also":["冒烟测试","smoke tests"]},{"id":"exploratory","g":"test","word":"探索式测试","text":"自由地使用产品，用各种方式去摸索，找出事先设计好的检查发现不了的问题。","also":["探索式测试","exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"测试用例","text":"一个写好的测试情境：要执行的步骤，以及应该出现什么结果。","also":["测试用例","test cases"]},{"id":"coverage","g":"test","word":"测试覆盖率","text":"有多少代码被自动测试检查过。通常越高越保险，但光有高覆盖率并不能证明它运行得好。","also":["覆盖率","代码覆盖率","code coverage"]},{"id":"testdata","g":"test","word":"测试数据","text":"测试时使用的虚构示例信息，这样就不会泄露任何真人的私人资料。","also":["测试数据","test fixtures"]},{"id":"edgecase","g":"test","word":"边界情况","text":"处于极限的特殊情形，比如空白的表单或带撇号的名字，这类地方常常出问题。","also":["边界情况","边缘情况","edge cases"]},{"id":"happypath","g":"test","word":"理想路径（Happy path）","text":"一切顺利的正常流程。好的测试也会试一试不顺利的路径。"},{"id":"perftest","g":"test","word":"性能测试","text":"检查某样东西有多快，以及在压力下撑得怎么样。","also":["性能测试","performance test","performance tests"]},{"id":"loadtest","g":"test","word":"负载测试","text":"检查很多人同时使用时，系统能否应付得来。","also":["负载测试","压力测试","load test","load tests"]},{"id":"sectest","g":"test","word":"安全测试","text":"寻找可能让人滥用系统、或看到不该看的内容的漏洞。","also":["安全测试","security test","security tests"]},{"id":"accesstest","g":"test","word":"无障碍测试","text":"检查能力各不相同的人是否都能使用产品，包括使用读屏软件或只用键盘的人。","also":["无障碍测试","可访问性测试","accessibility test"]},{"id":"linting","g":"test","word":"代码检查（Lint）","text":"自动检查，找出代码里可能的错误和杂乱的写法，就像程序的拼写检查。","also":["代码检查","linter","lint"]},{"id":"static","g":"test","word":"静态分析","text":"不运行代码，而是让电脑自动阅读代码来找出问题。","also":["静态分析","静态代码分析","static code analysis"]},{"id":"flaky","g":"test","word":"不稳定测试","text":"有时通过、有时失败，又说不清原因的测试，所以不能完全信任它。","also":["不稳定测试","flaky tests"]},{"id":"repro","g":"test","word":"复现","text":"照着同样的步骤让 bug 故意再出现一次，这样才能研究并修好它。把这些步骤写下来，是 bug 报告里最有用的部分。","also":["复现","重现","repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"严重程度","text":"一个问题造成的影响有多糟，从小小的麻烦到一切停摆。","also":["严重程度","严重性","severity level"]},{"id":"deploy","g":"change","word":"部署","text":"把软件的新版本复制到运行它的电脑上，比如测试副本或正式上线的服务。"},{"id":"release","g":"change","word":"发布","text":"一批有名字、一起上线的已完成工作，附带几句简短说明，讲清改了什么。🚀 发布会根据已完成的卡片写好这些说明。","also":["发布版本","release","releases"]},{"id":"rollback","g":"change","word":"回滚","text":"新版本出问题时，退回到上一个正常的版本。在 AI-gile 里，“回滚”会把每项改动上写好的撤销步骤汇总成一份清单。","also":["回退","rollback","roll back","roll-back","rolled back"]},{"id":"live","g":"change","word":"线上","text":"大家真正在用的那个版本，而不是用来试东西的副本。把东西放上去就叫上线。开发者也叫它生产环境。","also":["上线","生产环境","live","production"],"noTip":1},{"id":"change","g":"change","word":"变更","text":"对大家依赖的东西做的有计划的改动，事先写清楚：改什么、为什么、有什么风险、什么时候改、怎么撤销。用 🔀 提出变更 来开始。","also":["变更请求","change","change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"风险","text":"可能出错的事，按发生的可能性和严重程度打分。⚠️ 风险 把它们放在一个列表里，分数最高的在最前面，每条都有一个再次查看的日期。","also":["风险登记","risk","risks","risk register"]},{"id":"chgwin","g":"change","word":"变更窗口","text":"允许变更上线的时间，比如一个清闲的周二晚上。在窗口之外，变更卡片无法完成，除非是紧急情况。","also":["变更时段","change window","change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"改动上线前的最后检查：每位需要批准的人都要说 Go 或 No go。只有所有人都说 Go 才会继续。","also":["go/no go","go-no-go","上线决策"]},{"id":"approval","g":"change","word":"审批","text":"开工前先等一句“可以”。朋友提的卡片，或者一项变更，会在 ✅ 审批 里等着，直到你批准或拒绝。","also":["批准","approval","approvals"]},{"id":"quiettime","g":"change","word":"静默时段","text":"一段什么都不上线的时间，比如直播、演示期间或夜里。团队照常工作和测试，但上线要等到这段时间结束。在别处它叫变更冻结。","also":["变更冻结","封版","quiet time","quiet times","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"一种工作方式：开发软件的人和运行软件的人组成一个团队，大量使用自动化，让改动可以经常、安全地上线。"},{"id":"cicd","g":"change","word":"CI/CD（持续集成与持续交付）","text":"大家的改动经常合并到主版本里，而且每次都会自动检查（持续集成），所以软件随时都能一键上线（持续交付）。","also":["CI/CD","CI","CD","持续集成","持续交付","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"持续部署","text":"比持续交付更进一步：每项通过检查的改动都会自动上线，不需要按任何按钮。","also":["持续部署","continuous deployments"]},{"id":"pipeline","g":"change","word":"流水线（Pipeline）","text":"一项改动在上线的路上要经过的一连串自动步骤，比如构建、测试，然后部署。","also":["流水线","管道","pipelines"]},{"id":"environment","g":"change","word":"环境","text":"为某个用途单独准备的一份系统副本，比如一份用来开发、一份用来测试，还有一份是正式上线的。","also":["环境","environments"],"noTip":1},{"id":"devenv","g":"change","word":"开发环境","text":"开发者工作用的那份副本，通常在自己的电脑上，在这里弄坏了东西也不会影响到任何人。","also":["开发环境","dev environment"]},{"id":"testenv","g":"change","word":"测试环境","text":"专门用来测试的一份独立系统副本，不会碰到真正的服务。","also":["测试环境","test environments"]},{"id":"staging","g":"change","word":"预发布环境（Staging）","text":"按正式环境的样子搭好的最后一份副本，在改动上线前做最后检查。","also":["预发布环境","预发环境","staging environment"]},{"id":"artifact","g":"change","word":"构建产物","text":"一次构建产出的文件或文件包，可以用来存放、检查或上线。","also":["构建产物","build artifacts"]},{"id":"hotfix","g":"change","word":"紧急修复（Hotfix）","text":"因为重要的东西坏了，绕开正常计划、很快上线的紧急修复。","also":["紧急修复","热修复","hotfixes"]},{"id":"patch","g":"change","word":"补丁","text":"修复 bug 或堵住安全漏洞的小更新。尽快安装安全补丁很重要。","also":["补丁","patches","security patch","security patches","安全补丁"]},{"id":"version","g":"change","word":"版本号","text":"像 2.4.1 这样的标签，说明你用的是哪个版本。通常第一个数字在大改动时变化，最后一个数字在小修复时变化。","also":["版本号","语义化版本","version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"发布说明","text":"用简单的话列出一个版本里改了什么，写给使用者看，包括修复的问题和已知的限制。也叫更新日志。","also":["发布说明","更新日志","changelog","change log"]},{"id":"flag","g":"change","word":"功能开关","text":"功能的开关：新做的东西可以先隐藏着上线，之后再打开（或再关掉），不需要发布新版本。","also":["功能开关","feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"向前修复","text":"遇到有问题的版本时，不是退回旧版本，而是尽快发布一个改正后的新版本来修复。","also":["向前修复","rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"金丝雀发布","text":"先让一小部分人用上改动，看起来没问题再给所有人。名字来自矿工带到井下当预警的金丝雀。","also":["金丝雀发布","灰度发布","canary releases","canary"]},{"id":"bluegreen","g":"change","word":"蓝绿部署","text":"保留两份正式系统，一次性把大家切换到新的那份，万一出问题，可以马上切回去。","also":["蓝绿部署","blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"零停机部署","text":"让新版本上线，而服务始终不会对用户中断。","also":["零停机部署","零停机","zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"变更赋能","text":"帮助改动顺利成功：权衡风险、取得合适的批准，并选一个合适的时间。也叫变更管理。","also":["变更赋能","变更管理","change enablement","change management"]},{"id":"cab","g":"change","word":"变更咨询委员会（CAB）","text":"审查重要改动、并决定是否以及何时可以进行的小组。","also":["CAB","变更委员会"]},{"id":"stdchange","g":"change","word":"标准变更","text":"风险低、每次都用同样成熟做法完成的改动，所以事先就已经批准。","also":["标准变更","standard changes"]},{"id":"normchange","g":"change","word":"常规变更","text":"需要先检查并获得批准才能进行的改动。","also":["常规变更","普通变更","normal changes"]},{"id":"emergchange","g":"change","word":"紧急变更","text":"必须马上进行以修复或避免严重问题的改动，批准也相应更快。","also":["紧急变更","emergency changes"]},{"id":"automation","g":"change","word":"自动化","text":"让电脑自己完成重复的工作，这样更快，而且每次做法都一致。","also":["自动化","automated"],"noTip":1},{"id":"infra","g":"change","word":"基础设施","text":"软件运行所依靠的机器、网络和服务。","also":["基础设施","基础架构","infra"]},{"id":"iac","g":"change","word":"基础设施即代码（IaC）","text":"把服务器和设置写在跟代码放在一起的文件里，这样每次都能原样重建出来。","also":["IaC","基础设施即代码"]},{"id":"cloud","g":"change","word":"云","text":"通过互联网向大型供应商租用电脑、存储和服务，而不是自己拥有这些机器。","also":["云","云端","云计算","the cloud","cloud computing"]},{"id":"provider","g":"change","word":"云服务商","text":"通过互联网出租计算资源的公司，比如亚马逊云科技（AWS）、微软 Azure 或谷歌云。","also":["云服务商","云供应商","cloud providers"]},{"id":"hosting","g":"change","word":"托管","text":"你的应用或网站存放和运行的地方，让人们可以访问，通常是向某家公司租用的。","also":["托管","主机托管","虚拟主机"]},{"id":"domain","g":"change","word":"域名","text":"人们输入的网址，比如 example.com。域名按年租用，所以必须续费。","also":["域名","domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"域名系统的缩写：互联网的通讯录，把 example.com 这样的名字换成正确那台电脑的地址。","also":["域名系统","domain name system"]},{"id":"container","g":"change","word":"容器","text":"一个密封的包，里面装着应用和它需要的一切，所以在任何电脑上运行起来都一样。最有名的工具是 Docker。","also":["容器","containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"虚拟机（VM）","text":"在一台真实电脑里运行的“假电脑”，所以一台大机器可以当成很多台来用。","also":["VM","VMs","虚拟机","virtual machines"]},{"id":"serverless","g":"change","word":"无服务器（Serverless）","text":"运行代码却不用自己管任何服务器：需要时由服务商来运行，用多少付多少。"},{"id":"lb","g":"change","word":"负载均衡器","text":"把访客分散到好几台服务器上的东西，这样没有哪一台会被压垮。","also":["负载均衡器","负载均衡","load balancers"]},{"id":"cache","g":"change","word":"缓存","text":"把最近的结果放在手边的便利存储，这样同样的东西不用再去取或再算一遍。清除缓存有时能解决页面显示过时内容的问题。","also":["缓存","caches","caching","cached"]},{"id":"cdn","g":"change","word":"内容分发网络（CDN）","text":"遍布全球的一批服务器，在你的访客附近存放你的页面和图片副本，让它们很快加载出来。","also":["CDN","内容分发网络"]},{"id":"migration","g":"change","word":"迁移","text":"把数据或系统从旧的环境搬到新的环境，或者小心地改变数据库的结构。","also":["迁移","数据迁移","migrations","database migration"]},{"id":"service","g":"run","word":"服务","text":"你做出来、大家依赖的东西，比如网站或应用，有人照看着让它一直正常运行。勾选“此项目是一项服务”，再写上它提供什么、谁在用、谁值班。","also":["service","services"]},{"id":"uptimepct","g":"run","word":"正常运行时间","text":"一项服务有多少时间在正常工作，通常用百分比表示。99.9% 仍然允许每月停机大约 43 分钟。","also":["正常运行时间","可用时间","uptime","uptime percentage"]},{"id":"uptime","g":"run","word":"可用性检查","text":"每隔几分钟自动检查一次你的服务是否还在响应。如果连续失败几次，AI-gile 会自己开一张事故卡片。","also":["可用性检查","uptime checks"]},{"id":"statuspage","g":"run","word":"状态页","text":"一个公开页面，显示服务是否正常（绿、橙或红）以及最新进展，让使用者自己查看，不用来问。","also":["状态页面","status page","status pages"]},{"id":"desk","g":"run","word":"服务台","text":"使用你服务的人提出的问题和反馈都会汇集到这里。AI-gile 会把每一条归类为请求、事故或想法，如果看起来和已经反馈过的东西很像，也会告诉你。","also":["服务台","帮助台","help desk","helpdesk","service desk"]},{"id":"svcrequest","g":"run","word":"服务请求","text":"有人要的是普通的东西，比如新账号或一点帮助，而不是反馈有东西坏了。它会排队等候；事故优先处理。","also":["服务请求","请求","service request","service requests"]},{"id":"incident","g":"run","word":"事故","text":"现在对使用者来说坏了或不能正常工作的东西，比如网站打不开或非常慢。🔥 事故卡片会插队：先让它恢复正常。","also":["故障","incident","incidents"]},{"id":"major","g":"run","word":"重大事故","text":"大事故：影响很多人，或者钱或数据有危险。一个按钮就能让所有团队都扑上去（蜂群），叫醒值班的人，并要求每 30 分钟更新一次状态。","also":["重大事件","重大故障","major incident","major incidents"]},{"id":"oncall","g":"run","word":"值班","text":"就是出问题时负责响应的人，哪怕是半夜。每项服务都有一位值班的团队成员，它的事故会最先叫醒这个人。","also":["值班人员","待命","on call","on-call"]},{"id":"replyby","g":"run","word":"回复期限","text":"一张卡片最多能等多久得到第一次回复，比如事故是一小时。超过之后它会出现一个红色时钟，免得有事被悄悄忘掉。也叫响应目标。","also":["响应目标","响应时间","reply-by time","response target","response targets"]},{"id":"postmortem","g":"run","word":"复盘","text":"事故之后的简短回顾：发生了什么、什么起了作用、要改什么，不追究任何人的责任。没有复盘，事故就不能关闭。","also":["事故复盘","事后复盘","post-mortem","post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"问题","text":"一个或多个事故背后的隐藏原因。🧩 问题卡片会把反复出现的事故归到一起，好找到原因并彻底修好。","also":["problem","problems"],"noTip":1},{"id":"rootcause","g":"run","word":"根本原因","text":"东西坏掉的真正原因，而不只是你看到的表面故障。修好根本原因，事故就不会再回来。","also":["根因","root cause","root causes"]},{"id":"workaround","g":"run","word":"临时解决办法","text":"在真正的修复做好之前让东西继续运转的办法，比如卡住时重启一下。它会写在问题卡片上，这样谁都不用再摸索一遍。","also":["临时方案","绕过办法","workaround","workarounds"]},{"id":"knownerror","g":"run","word":"已知错误","text":"原因已经搞清楚、也有临时解决办法，但还没修好的问题。🧩 已知错误 把它们列出来，大家直接用临时解决办法，不用再重新排查。","also":["known error","known errors"]},{"id":"runbook","g":"run","word":"运行手册","text":"处理某类已知问题的分步说明，让每次都用同样的方式快速搞定。重大事故之后，团队可以起草一份运行手册，交给你确认。","also":["操作手册","runbook","runbooks"]},{"id":"ci","g":"run","word":"配置项","text":"你的服务所依赖的某样东西，比如服务器、域名、证书、密钥或供应商。🗂️ 配置项按服务把它们列出来，让你看清一起事故会影响到什么，以及哪些东西需要续期或备份。","also":["配置项","配置条目","configuration item","configuration items","CI"]},{"id":"expiry","g":"run","word":"到期日","text":"某样东西不续期就会失效的日期，比如网站的安全证书或网址。AI-gile 会盯着这些日期，并在到期前 30 天为每一项建一张续期卡片，这样什么都不会突然失效。","also":["到期日","到期","到期提醒","expiry date","expiry dates","expiry"]},{"id":"backup","g":"run","word":"备份","text":"你的数据之前保存下来的一份副本，万一有东西丢了或坏了可以靠它。AI-gile 每天都会备份你的看板。","also":["backup","backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"恢复","text":"从备份里把数据放回去。只有确认能恢复，备份才算真正有用，所以值得时不时试一下。","also":["还原","已恢复","restore","restored"]},{"id":"svcreview","g":"run","word":"服务回顾","text":"回看一项服务的一个月：开启和修复的事故、大家多快得到答复、正常运行时间，以及用掉的 token。月度回顾会为每项服务展示这些内容。","also":["服务回顾","月度回顾","每月回顾","service review","monthly review"]},{"id":"accessreview","g":"run","word":"访问审查","text":"每 90 天检查一次谁还能进来：分享链接、朋友的角色，以及保存的密码和密钥。每一项由你决定保留或移除，这样旧的访问权限不会一直留着。","also":["访问审查","权限审查","access review","access reviews"]},{"id":"improvements","g":"run","word":"改进清单","text":"团队决定要做得更好的所有事情，集中在一个地方：回顾会的建议、复盘的行动项和问题的修复，每一项都带有状态。在 📈 改进 里就能找到。","also":["改进清单","改进","improvement list","improvements"]},{"id":"tokencap","g":"run","word":"Token 上限","text":"一项服务的智能体每月可用 token 的上限。达到 80% 时你会收到警告；达到 100% 时，它们的后台工作会等到下个月，或等你调高上限。","also":["token 上限","每月 token 上限","token cap","token caps"]},{"id":"svcmgmt","g":"run","word":"服务管理","text":"为了让一项服务日复一日地对依赖它的人保持有用、正常运作所做的一切。","also":["服务管理"]},{"id":"itil","g":"run","word":"ITIL","text":"一套广泛使用的服务管理最佳实践指南，涵盖事故、问题和变更等内容。这个名字原本是 IT 基础架构库（IT Infrastructure Library）的缩写。"},{"id":"itsm","g":"run","word":"IT 服务管理（ITSM）","text":"把技术当作一项为人提供的服务来运营，用清晰的方式处理请求、事故、变更和改进。","also":["ITSM","IT 服务管理"]},{"id":"managed","g":"run","word":"托管服务","text":"由别人替你运营和维护的服务，并按协议保证它要达到的水准。","also":["托管服务","managed services"]},{"id":"svcowner","g":"run","word":"服务负责人","text":"为整项服务负责的人：它运作得怎么样、花多少钱、怎样改进。","also":["服务负责人","服务所有者","service owners"]},{"id":"sla","g":"run","word":"服务水平协议（SLA）","text":"对客户做出的书面承诺，说明服务会达到什么水准，比如“99.9% 的时间可用”或“一小时内回复”，没做到时往往要退款。","also":["SLA","SLAs","服务水平协议","service level agreement"]},{"id":"slo","g":"run","word":"服务水平目标（SLO）","text":"团队自己定的目标，说明一项服务在一段时间内应该达到什么水准，通常比 SLA 定得更严一点，以求稳妥。","also":["SLO","SLOs","服务水平目标"]},{"id":"sli","g":"run","word":"服务水平指标（SLI）","text":"拿来和目标对照的实际测量值，比如正常加载的访问所占的比例。","also":["SLI","SLIs","服务水平指标"]},{"id":"availability","g":"run","word":"可用性","text":"人们需要时能不能用上这项服务，常用正常运行时间来衡量。","also":["可用性","高可用","high availability"]},{"id":"downtime","g":"run","word":"停机时间","text":"服务无法工作或被关掉的时间，无论是计划内的还是计划外的。","also":["停机时间","停机","down time"]},{"id":"errorbudget","g":"run","word":"错误预算","text":"可靠性目标所允许的那一点点失败。还有剩余时，可以对改动冒些风险；用完了，就要放慢脚步。","also":["错误预算","error budgets"]},{"id":"outage","g":"run","word":"故障停服","text":"服务对用户来说停了或严重出毛病的一段时间。","also":["故障停服","服务中断","宕机","outages"]},{"id":"degraded","g":"run","word":"服务降级","text":"还能用，但状态很差：很慢，或者有些部分不能用。","also":["服务降级","性能下降","degraded service"]},{"id":"monitoring","g":"run","word":"监控","text":"随时自动盯着一项服务，这样问题能被发现，最好是在用户察觉之前。","also":["监控","监测"]},{"id":"observability","g":"run","word":"可观测性","text":"能凭借系统的日志、数据和追踪记录，从外部看清系统内部发生了什么的程度。","also":["可观测性","o11y"]},{"id":"log","g":"run","word":"日志","text":"程序一直在写的流水日记，记录它在做什么，用来查明哪里出了问题。","also":["日志","logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"追踪（Trace）","text":"一个请求一步步穿过系统各个部分的记录，能看出它在哪里变慢了。","also":["追踪","链路追踪","traces","tracing"]},{"id":"latency","g":"run","word":"延迟","text":"得到回应要花多长时间，比如从点击到页面出现之间的等待。","also":["时延"]},{"id":"alert","g":"run","word":"告警","text":"自动发出的消息，告诉你有事需要处理，比如网站没有响应。","also":["告警","警报","提醒","alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"告警疲劳","text":"告警多到人们开始不理会，连重要的也一起忽略。","also":["告警疲劳","警报疲劳","alarm fatigue"]},{"id":"dashboard","g":"run","word":"仪表盘","text":"一个屏幕，让你一眼看到最重要的数字和状态。","also":["仪表盘","仪表板","dashboards"],"noTip":1},{"id":"paging","g":"run","word":"呼叫值班人员（Paging）","text":"为了某个问题，紧急打电话或叫醒当班待命的人。","also":["紧急呼叫","寻呼","paged"]},{"id":"escalation","g":"run","word":"升级上报","text":"当问题在目前这一层解决不了、或解决得不够快时，请更有经验或更有权限的人来处理。","also":["升级上报","问题升级","escalate","escalated"]},{"id":"triage","g":"run","word":"分诊（Triage）","text":"按紧急和重要的程度，快速给收到的问题分类，让最严重的先得到处理。","also":["分诊","分流","triaged"]},{"id":"impact","g":"run","word":"影响范围","text":"某件事影响人的程度：影响多少人，影响多严重。","noTip":1},{"id":"urgency","g":"run","word":"紧急程度","text":"某件事需要多快处理。影响范围和紧急程度合起来，就决定了优先级。","noTip":1},{"id":"plevels","g":"run","word":"优先级等级（P1、P2…）","text":"表示问题有多紧急的标签。P1 最严重，需要立刻行动。","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"工单队列","text":"等着有人来接手的请求和事故的清单。","also":["工单队列","ticket queues"]},{"id":"tiers","g":"run","word":"一线与二线","text":"支持的层级：一线负责接电话、解决简单的问题；二线有更深的技能，处理更难的问题。也叫 tier 1 和 tier 2（一级和二级支持）。","also":["一线","二线","一线支持","first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"事故指挥官","text":"统一指挥事故应对的那一个人，这样每个人都知道谁来拍板、谁做什么。","also":["事故指挥官","事件指挥官","incident commanders"]},{"id":"responsetime","g":"run","word":"响应时间","text":"从提出一个请求或报告一起事故，到有人第一次接手，中间要多久。","also":["响应时间","response times"]},{"id":"resolution","g":"run","word":"解决时间","text":"把一个请求或一起事故完全处理好要多久，从报告到修好。","also":["解决时间","time to resolve","resolution times"]},{"id":"mttr","g":"run","word":"平均恢复时间（MTTR）","text":"平均来说，服务出故障后要花多久才能恢复正常。MTTR 的含义可能略有不同，所以要说明你量的是什么。","also":["MTTR","平均修复时间","mean time to restore"]},{"id":"mtbf","g":"run","word":"平均故障间隔时间（MTBF）","text":"平均来说，一项服务运行多久才会出一次问题。","also":["MTBF","平均无故障时间"]},{"id":"cmdb","g":"run","word":"配置管理数据库（CMDB）","text":"列出你所有配置项及其相互关系的清单，让你看出什么依赖什么。","also":["CMDB","配置管理库"]},{"id":"asset","g":"run","word":"资产","text":"你为运行服务而拥有或付费的任何有价值的东西，比如一台笔记本电脑、一份软件许可或一个域名。","also":["资产","assets"],"noTip":1},{"id":"capplan","g":"run","word":"容量规划","text":"确保对即将到来的需求，有足够的计算能力、存储空间和人手。","also":["容量规划","capacity plan"]},{"id":"scaling","g":"run","word":"扩容","text":"应对更多用户的办法：给一台机器增加性能（纵向扩展），或者增加更多机器（横向扩展）。","also":["扩容","扩展","纵向扩展","横向扩展","scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"业务连续性","text":"当出现大问题（比如失去办公室、关键供应商或所有电脑）时，让重要的事情继续运转的计划。","also":["业务连续性","业务连续性计划","business continuity plan"]},{"id":"dr","g":"run","word":"灾难恢复（DR）","text":"发生严重状况（比如整个数据中心都没了）之后，把服务恢复回来的计划和工具。","also":["灾难恢复","灾备","disaster recovery"]},{"id":"rto","g":"run","word":"恢复时间目标（RTO）","text":"灾难发生后，服务最长可以停多久，之后就必须恢复运作。","also":["RTO","恢复时间目标"]},{"id":"rpo","g":"run","word":"恢复点目标（RPO）","text":"你能承受损失多少最近的数据，以时间来衡量。RPO 为一小时，就表示至少每小时备份一次。","also":["RPO","恢复点目标"]},{"id":"redundancy","g":"run","word":"冗余","text":"准备好备用设备，比如第二台服务器，这样一处故障不会让服务停摆。","also":["冗余","备援"]},{"id":"failover","g":"run","word":"故障转移","text":"平时用的系统出故障时，自动切换到备用系统。","also":["故障转移","故障切换","fail over"]},{"id":"spof","g":"run","word":"单点故障","text":"某个部分一旦坏掉就会连累整体，因为没有备用的。","also":["单点故障","single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"维护窗口","text":"为了保养而计划好的一段时间，服务可能暂停或变慢，会提前通知用户。","also":["维护窗口","计划维护","maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"交接","text":"把工作、知识和责任交给另一个人或团队，这样不会有东西被漏掉。","also":["交接","工作交接","handovers"]},{"id":"kb","g":"run","word":"知识库","text":"一批帮助文章和解答的集合，给用户看，也给团队看。","also":["知识库","knowledge bases"]},{"id":"csat","g":"run","word":"客户满意度（CSAT）","text":"用户给出的分数，表示他们有多满意，通常在请求处理完毕后询问。","also":["CSAT","满意度"]},{"id":"supplier","g":"run","word":"供应商","text":"你所依赖的外部公司，比如你的托管服务商。也叫厂商或第三方。","also":["供应商","厂商","第三方","suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"服务退役","text":"安全地把一项服务永久关闭：通知它的用户、处理它的数据和访问权限，并停止它的费用。","also":["服务退役","下线服务","retiring a service"]},{"id":"eol","g":"run","word":"生命周期结束（EOL）","text":"产品不再有厂商提供的更新或支持，所以应该换掉了。","also":["EOL","end-of-life","停止支持"]},{"id":"cybersec","g":"sec","word":"网络安全","text":"保护系统和数据，不被闯入、窃取或破坏。","also":["网络安全","cyber security"]},{"id":"authn","g":"sec","word":"身份验证","text":"确认一个人是谁，通常靠密码或验证码。常简写为 authn。","also":["身份验证","身份认证","authn"]},{"id":"authz","g":"sec","word":"授权","text":"在知道对方是谁之后，确认他被允许做什么。常简写为 authz。","also":["授权","权限授予","authz","authorization"]},{"id":"mfa","g":"sec","word":"多因素身份验证（MFA）","text":"用两种或更多的证明来登录，比如密码加上手机上的验证码。也叫双因素验证（2FA）。","also":["MFA","2FA","两步验证","双因素","双因素认证","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"单点登录（SSO）","text":"登录一次就能进入很多系统，就像到处都用你的工作账号。","also":["SSO","单点登录"]},{"id":"pwmgr","g":"sec","word":"密码管理器","text":"一个能生成高强度密码并替你记住它们的应用。","also":["密码管理器","密码管理工具","password managers"]},{"id":"secret","g":"sec","word":"机密信息（Secret）","text":"程序用来进入某处的密码、密钥或其他私密口令。绝不能分享，也不能写进代码里。","also":["机密","密钥","secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API 密钥","text":"一串保密的代码，让程序可以使用另一项服务的 API，并显示是谁在用（以及谁在付费）。","also":["API 密钥","API key","API keys"]},{"id":"accesstoken","g":"sec","word":"访问令牌","text":"一张临时通行证，证明程序被允许进入，这样不必每次都用你的密码。它和 AI 用量里的 Token 不是一回事。","also":["访问令牌","令牌","access tokens"]},{"id":"encryption","g":"sec","word":"加密","text":"把信息打乱，只有拿着正确密钥的人才能读懂。","also":["加密","encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"网页传输的安全方式，浏览器里的小锁图标就是标志，这样中间没有人能读取或篡改。"},{"id":"cert","g":"sec","word":"SSL/TLS 证书","text":"一张数字身份证，让网站能证明自己的身份并使用 HTTPS。证书会过期，所以必须续期。","also":["TLS 证书","SSL 证书","证书","TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"权限","text":"规定谁可以查看或修改什么的规则。","also":["权限","permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"最小权限原则","text":"只给每个人或程序真正需要的访问权限，而且只在需要的时候给。","also":["最小权限","最小特权","principle of least privilege"]},{"id":"rbac","g":"sec","word":"基于角色的访问控制（RBAC）","text":"按角色（比如查看者或编辑者）来授予权限，而不是一个人一个人地设置。","also":["RBAC","角色权限控制","role-based access"]},{"id":"vuln","g":"sec","word":"漏洞","text":"别人可能利用来闯入或造成破坏的弱点。","also":["漏洞","安全漏洞","vulnerabilities"]},{"id":"zeroday","g":"sec","word":"零日漏洞","text":"攻击者知道、而厂商还没来得及修复的弱点。","also":["零日漏洞","零日","zero-days","zero day"]},{"id":"malware","g":"sec","word":"恶意软件","text":"有害的软件，比如病毒，用来破坏、窥探或窃取。","also":["恶意软件"]},{"id":"ransomware","g":"sec","word":"勒索软件","text":"把你的文件锁起来、要你付钱才解锁的恶意软件。做好备份是最好的防御。","also":["勒索软件","勒索病毒","ransomware attack"]},{"id":"phishing","g":"sec","word":"网络钓鱼","text":"伪造的消息，想骗你交出密码或钱，或者打开有害的东西。","also":["网络钓鱼","钓鱼邮件","phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"社会工程学","text":"骗的不是电脑而是人，让人交出访问权限，比如冒充“IT 支持”打来的假电话。"},{"id":"firewall","g":"sec","word":"防火墙","text":"一个守卫，决定哪些网络流量可以进来或出去。","also":["防火墙","firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"虚拟专用网的缩写：在互联网上建立的一条私密、加密的连接，常用来安全地访问工作系统。","also":["虚拟专用网","虚拟专用网络","virtual private network"]},{"id":"ddos","g":"sec","word":"拒绝服务攻击（DoS、DDoS）","text":"用大量假流量淹没一项服务，让真正的人用不了。DDoS 指这些流量同时来自许多台电脑。","also":["DoS","DDoS","拒绝服务","拒绝服务攻击","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"渗透测试","text":"请友好的专家试着闯进来，这样在真正的攻击者发现之前，先找出弱点。","also":["渗透测试","pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"安全审计","text":"对照一份良好做法的清单，仔细检查某样东西保护得怎么样。","also":["安全审计","安全检查","security audits"]},{"id":"threatmodel","g":"sec","word":"威胁建模","text":"想清楚谁可能攻击某样东西、怎么攻击，以及你会怎么阻止他们。","also":["威胁建模","威胁模型","threat model","threat modeling"]},{"id":"breach","g":"sec","word":"数据泄露","text":"私人信息落到不该拿到的人手里，或者未经许可就丢失或被改动。","also":["数据泄露","数据外泄","data breaches"]},{"id":"pii","g":"sec","word":"个人数据","text":"任何关于可识别身份的人的信息，比如姓名、邮箱地址或位置。也叫 PII。","also":["个人数据","个人信息","PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"欧洲关于个人数据的法律（英国有自己的版本）：只收集需要的、妥善保管，并让人们可以查看或删除自己的数据。","also":["通用数据保护条例","General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"数据保护","text":"依法妥善地保管个人数据。","also":["数据保护","数据保护法","data protection law"]},{"id":"privacypolicy","g":"sec","word":"隐私政策","text":"一个公开的页面，说明你收集哪些个人数据、为什么收集，以及怎么处理。","also":["隐私政策","隐私声明","隐私条款","privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"同意","text":"一个人明确、自愿地答应：他的数据可以按某种方式使用。他随时可以收回。","also":["同意","用户同意","opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"网站存放在你浏览器里的小文件，用来记住一些事情，比如你已登录。有些需要先取得你的同意。","also":["Cookie","cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"数据最小化","text":"只收集并保留完成这项工作真正需要的个人数据。","also":["数据最小化","data minimization"]},{"id":"retention","g":"sec","word":"数据保留","text":"数据在被删除之前保存多久。不超过需要的时间，更安全，往往也是法律要求。","also":["数据保留","保留期限","retention period"]},{"id":"anon","g":"sec","word":"匿名化","text":"改动数据，使任何人都无法再通过合理手段从中认出具体是谁。","also":["匿名化","匿名数据","anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"假名化","text":"把姓名和其他细节换成代码，另外保管一把密钥用来对应回去。它仍然属于个人数据。","also":["假名化","化名处理","pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"数据处理协议（DPA）","text":"一份合同，规定供应商可以怎样代你处理个人数据。","also":["DPA","数据处理协议"]},{"id":"dpia","g":"sec","word":"数据保护影响评估（DPIA）","text":"在开始之前，仔细审视使用个人数据的计划会对人们产生什么影响，以及如何降低风险。","also":["DPIA","数据保护影响评估"]},{"id":"auditlog","g":"sec","word":"审计日志","text":"记录谁在什么时候做了什么，这样日后可以核查这些操作。","also":["审计日志","审计记录","audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"合规","text":"遵守适用于你的法律、规则和标准，并且能证明你做到了。","also":["合规","合规性","compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"管理信息安全的一项著名国际标准。公司可以申请按它认证。","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"美国的一种报告，由外部审计人员检查，证明一家公司妥善地保管客户数据。","also":["SOC2"]},{"id":"agent","g":"ai","word":"智能体","text":"独立处理任务的 AI：读代码、做改动、运行检查，并汇报结果。它的工作仍然会被检查。","also":["agents","Agent","agent"]},{"id":"token","g":"ai","word":"Token","text":"AI 阅读和书写的文字小片段，每个大约相当于四分之三个单词。AI 的用量按 Token 计算，所以用的 Token 越少，你的套餐剩得越多。","also":["tokens"]},{"id":"hook","g":"ai","word":"钩子","text":"在特定时刻自动运行的小命令，比如 AI 会话开始时，这样团队就能听到你的评论。","also":["hooks","Hook","hook"]},{"id":"ai","g":"ai","word":"人工智能（AI）","text":"能做一些我们通常认为需要人才能做的事的电脑系统，比如写作、回答问题或识别图片。","also":["AI","人工智能","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"机器学习（ML）","text":"让电脑从大量例子中学会规律的方法，而不是给它精确的规则。","also":["机器学习","machine learning"]},{"id":"model","g":"ai","word":"模型","text":"AI 系统经过训练的“大脑”，通过学习海量例子而成。不同模型在能力、速度和价格上各不相同。","also":["模型","AI 模型","models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"大语言模型（LLM）","text":"用海量文字训练出来的 AI 模型，所以能阅读和书写语言。","also":["LLM","LLMs","大语言模型","大型语言模型"]},{"id":"genai","g":"ai","word":"生成式 AI","text":"能创造新东西（比如文字、图片或代码）的 AI，而不只是分类或识别。","also":["生成式 AI","生成式人工智能","GenAI"]},{"id":"chatbot","g":"ai","word":"聊天机器人","text":"你可以用日常语言和它交谈的程序，打字或说话都行。","also":["聊天机器人","对话机器人","chatbots"]},{"id":"prompt","g":"ai","word":"提示词（Prompt）","text":"你交给 AI 的内容：你的问题或指示，加上你给它的任何材料。提示词越清楚，通常得到的回答越好。","also":["提示词","提示","指令","prompts"]},{"id":"prompteng","g":"ai","word":"提示词工程","text":"写出能得到可靠、有用结果的提示词的技巧。","also":["提示词工程","提示工程"]},{"id":"sysprompt","g":"ai","word":"系统提示词","text":"AI 在对话开始前就收到的背景指示，设定它的角色和规则。它比你输入的内容分量更重。","also":["系统提示词","系统提示","system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"上下文","text":"AI 工作时能看到的一切：指示、你的消息、它读过的文件，以及之前的回复。","noTip":1},{"id":"ctxwin","g":"ai","word":"上下文窗口","text":"AI 一次能记在心里的量，以 Token 计算。超过之后，较早的部分会被丢掉或概括。","also":["上下文窗口","context windows"]},{"id":"session","g":"ai","word":"会话","text":"与 AI 的一次完整的工作对话，从头到尾。新的会话从全新的记忆开始。","also":["会话","sessions"],"noTip":1},{"id":"memory","g":"ai","word":"记忆","text":"AI 在不同会话之间保留的笔记，让它记得你的偏好和以前做过的决定。","noTip":1},{"id":"hallucination","g":"ai","word":"幻觉","text":"AI 说的话听起来很有把握，其实是编出来的或是错的。重要的事实要核对。","also":["幻觉","AI 幻觉","hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"训练","text":"在有人使用之前，让模型看海量的例子来教会它。","also":["训练","trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"训练数据","text":"模型学习所用的那些例子。它的知识截止到这些数据收集的日期。","also":["训练数据","训练集","training set"]},{"id":"cutoff","g":"ai","word":"知识截止日期","text":"AI 内置知识结束的日期。之后发生的事它不知道，除非它去查。","also":["知识截止日期","训练截止日期","training cutoff"]},{"id":"finetune","g":"ai","word":"微调","text":"用你自己的例子给现成的模型额外训练一轮，让它更擅长某一项具体的工作。","also":["微调","fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"推理","text":"AI 模型真正被用来回答问题，而不是在接受训练。","also":["推理","模型推理","model inference"]},{"id":"tooluse","g":"ai","word":"工具调用","text":"AI 不只会说话，还能做事：通过应用提供给它的工具来运行命令、读取文件或搜索网页。","also":["工具调用","使用工具","tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"子智能体","text":"主 AI 把较小的工作交给它、并从它那里拿回结果的帮手 AI。","also":["子智能体","subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"多智能体","text":"好几个 AI 一起处理同一项工作，各有各的分工，就像一个小团队。","also":["多智能体","多智能体系统","multi-agent system"]},{"id":"autonomy","g":"ai","word":"自主性","text":"AI 在必须问人之前，可以自己做多少事。","also":["自主性","自主","autonomous"]},{"id":"hitl","g":"ai","word":"人在回路","text":"让人参与进来，在关键节点检查或批准 AI 的所作所为。在 AI-gile 里，这个人就是你。","also":["人在回路","人工参与","human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"护栏","text":"让 AI 的行动保持安全的限制和检查，比如任何东西上线前都要先得到批准。它们能降低出错的风险，但不能完全杜绝。","also":["护栏","防护措施","guardrail"]},{"id":"rag","g":"ai","word":"检索增强生成（RAG）","text":"让 AI 在回答之前，先到你自己的文档里查资料，这样它的回答是以你的事实为依据的。","also":["RAG","检索增强生成","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"嵌入（Embedding）","text":"把文字变成一串能体现其含义的数字，这样电脑就能找出意思相近的内容。","also":["嵌入","向量嵌入","embeddings"]},{"id":"vectordb","g":"ai","word":"向量数据库","text":"专门用来搜索这些数字串（嵌入）的数据库，用来找出含义相近的资料。","also":["向量数据库","向量库","vector databases","vector store"]},{"id":"mcp","g":"ai","word":"模型上下文协议（MCP）","text":"把工具和数据源接入 AI 应用的一种通用方式，这样 AI 就能使用它们。","also":["MCP","模型上下文协议"]},{"id":"temperature","g":"ai","word":"温度（Temperature）","text":"控制 AI 回答有多“大胆”的设置。低的话回答更稳定、更可预测；高的话更多变。但两种都不能保证永远正确。","also":["温度","模型温度","model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"多模态","text":"能处理不止一种信息，比如文字、图片和声音。","also":["多模态","multi-modal"]},{"id":"evals","g":"ai","word":"评估（Eval）","text":"用挑选好的例子，有计划地测试 AI 表现如何，这样可以比较不同的模型或提示词。","also":["评估","评测","eval","evals"]},{"id":"bias","g":"ai","word":"偏见","text":"AI（或人）不公平地偏向某一边，往往是因为它学习的材料有偏。","also":["偏见","偏差","biased"],"noTip":1},{"id":"responsible","g":"ai","word":"负责任的 AI","text":"公平、安全、诚实地使用 AI，并且结果仍由人来负责。","also":["负责任的 AI","AI 伦理","ethical AI"]},{"id":"injection","g":"ai","word":"提示词注入","text":"一种花招：网页或文件里藏着的指示，企图让 AI 去做用户没有要求的事。","also":["提示词注入","提示注入","prompt injections"]},{"id":"ratelimit","g":"ai","word":"速率限制","text":"在一定时间内，你能向服务发送多少请求的上限。超过了就得等一等。","also":["速率限制","限流","rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"用量限额","text":"你的套餐在一段时间内允许多少 AI 工作量，超过之后会暂停或要多付钱。","also":["用量限额","使用限额","usage limits"]},{"id":"vibe","g":"ai","word":"氛围编程（Vibe coding）","text":"主要靠向 AI 描述你想要什么、让它来写代码，从而做出软件。","also":["氛围编程","vibe-coding"]},{"id":"budget","g":"money","word":"预算","text":"为某件事预留的钱。","also":["预算","budgets"],"noTip":1},{"id":"costest","g":"money","word":"成本估算","text":"在开始之前，对某件事要花多少钱的最佳猜测。","also":["成本估算","费用估算","cost estimates"]},{"id":"roi","g":"money","word":"投资回报率（ROI）","text":"你得到的回报与你投入的相比如何。如果是正数，就说明值得。","also":["ROI","投资回报","投资回报率"]},{"id":"tco","g":"money","word":"总拥有成本（TCO）","text":"某样东西在整个生命周期里真正的全部花费，而不只是买它的价钱：运行、支持、升级，最后还有淘汰它。","also":["TCO","总拥有成本"]},{"id":"capex","g":"money","word":"资本支出与运营支出（CapEx 和 OpEx）","text":"CapEx 是一次性预先花在能长期保留的东西上的钱；OpEx 是持续的支出，比如每月的账单。","also":["CapEx","OpEx","资本支出","运营支出","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"订阅","text":"定期付费（通常按月或按年），以便继续使用某样东西。","also":["订阅","subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"软件即服务（SaaS）","text":"在线使用、按订阅付费的软件，由开发商替你运营。","also":["SaaS","软件即服务"]},{"id":"payg","g":"money","word":"按量付费","text":"只为你用到的部分付钱，比如云计算或 AI 的 Token。","also":["按量付费","用多少付多少","pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"超额使用","text":"用量超出套餐包含的部分，可能要额外收费。","also":["超额使用","超出用量","overages","overage charges"]},{"id":"billingalert","g":"money","word":"账单提醒","text":"花费或用量达到你设定的水平时发出的消息。它会提醒你，但不一定会阻止之后继续扣费。","also":["账单提醒","费用提醒","billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"免费额度","text":"付费服务里带有限制的免费级别。刚开始用很方便。","also":["免费额度","免费版","free plan"]},{"id":"pricing","g":"money","word":"定价方案","text":"一项服务出售的各种套餐，每种有自己的价格和限制。","also":["定价方案","价格方案","套餐","pricing plans","price plan"]},{"id":"licence","g":"money","word":"许可证","text":"规定你可以怎样使用、复制、修改或分享别人做的东西（比如软件、字体或图片）的规则。","also":["许可证","许可","授权","licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"开源","text":"代码人人都能阅读、使用、而且往往可以免费修改的软件，要遵守其许可证的规定。","also":["开源","开放源代码","open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"开源许可证","text":"开源代码附带的规则。有的几乎什么都允许（比如 MIT），有的要求你也分享你的修改（比如 GPL）。","also":["开源许可证","开源协议","open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"专有软件","text":"归某家公司所有，不能随便复制或修改。与开源相反。","also":["专有软件","闭源软件","proprietary software"]},{"id":"copyright","g":"money","word":"版权","text":"创作者控制自己作品（包括代码和文字）的复制的法定权利。","also":["版权","著作权","copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"知识产权（IP）","text":"法律视为有所有者的想法和创作，比如代码、设计、名称和标志。","also":["知识产权","intellectual property"]},{"id":"tos","g":"money","word":"服务条款","text":"你使用某项服务时所同意的规则。","also":["服务条款","使用条款","terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"合同","text":"双方之间的书面协议，受到法律保护。","also":["合同","合约","contracts"],"noTip":1},{"id":"sow","g":"money","word":"工作说明书（SOW）","text":"一份文件，写明具体要做哪些工作、什么时候完成、收多少钱。","also":["SOW","工作说明书"]},{"id":"fixedprice","g":"money","word":"固定价格","text":"整项工作约定好一个价格，不管花多长时间。","also":["固定价格","固定报价","fixed-price"]},{"id":"tm","g":"money","word":"按工时和材料计费","text":"按实际做的工时和实际用到的东西付费，而不是固定价格。","also":["按工时计费","T&M"]},{"id":"invoice","g":"money","word":"发票","text":"为已完成的工作或已提供的商品要求付款的账单。","also":["发票","账单","invoices"],"noTip":1},{"id":"lockin","g":"money","word":"供应商锁定","text":"离开某个供应商太难或太贵，结果你只好一直被它绑住。","also":["供应商锁定","厂商锁定","lock-in"]},{"id":"procurement","g":"money","word":"采购","text":"挑选并向供应商购买东西的过程。","also":["采购"]},{"id":"servicecredit","g":"money","word":"服务抵扣金","text":"供应商没达到 SLA 时，你得到的退款或折扣。","also":["服务抵扣金","服务补偿","service credits"]}]}};
